command:
// ======================================================================
// === GABE: MÄUSEMEISTER (APHASMA) =====================================
// ======================================================================

const gabenName = "Mäusemeister (Aphasmakind)";
const effektName = `Aktiver Effekt: Mäusemeister`;
const symbolPfad = "https://assets.forge-vtt.com/644fbc20a9e089e2ef894956/modules/dsk-core/icons/journal/image-440.webp";

// QS aus Testergebnis oder Standard 1
const qsWert = Number(testData?.result?.QL || testData?.qualityStep || 1);
if (qsWert <= 0) return ui.notifications.warn("Die Probe ist fehlgeschlagen.");

const dauerMinuten = qsWert;

// 1. EFFEKT SETZEN
let alterEffekt = actor.effects.find(e => e.name === effektName);
if (alterEffekt) await alterEffekt.delete();

await actor.createEmbeddedDocuments("ActiveEffect", [{
    name: effektName, 
    icon: symbolPfad, 
    disabled: false, 
    origin: actor.uuid, 
    duration: { minutes: dauerMinuten },
    changes: [{
        key: "flags.dsk.status", 
        mode: 2, 
        value: "Verwandelt in Maus",
        priority: 20
    }]
}]);

// 2. CHAT-NACHRICHT (FESTES LAYOUT)
const html = `
<div style="font-family: 'Signika', sans-serif;">
    <div class="dskbox1">
        <p style="display:flex; align-items:center; gap:8px;">
            <img src="${symbolPfad}" style="width:28px;"> <b>Ahnengabe</b>
        </p>
        <p style="text-align:center; font-weight:bold; margin-top:6px;">${gabenName}</p>
    </div>
    <div class="dskbox2" style="margin-top:10px;">
        <p>🔮 <b>${actor.name}</b> wirkt Mäusemeister.</p>
        <p>• <b>Verwandlung:</b> @UUID[Compendium.dsk-core.corebestiary.Actor.BaGVz4HqAZ0QXxsi]{Maus}<br>
        <i style="font-size: 0.9em;">Das Ziel behält einen Teil seines Geistes, übernimmt jedoch die körperlichen Fähigkeiten einer Maus.</i></p>
        <hr>
        <p>🟡 <b>Wirkungsdauer:</b> ${dauerMinuten} Minuten</p>
    </div>
</div>`;

await ChatMessage.create({
    content: html,
    speaker: { alias: gabenName }
});
